  const STAGE_TARGET = { food: 0x5d6b2e, metal: 0x7a3e1d, wood: 0x3f3326, cloth: 0x4a4033, plastic: 0x6b6556, paper: 0x8a7a52, glass: 0x55503a };
  const AMT = [0, .3, .62];
  function setStage(s) {
    const tmp = new T.Color();
    mats.forEach(m => {
      const t = STAGE_TARGET[m.userData.tag]; if (t === undefined) return;
      tmp.setHex(t); m.color.copy(m.userData.base).lerp(tmp, AMT[s]);
      m.roughness = Math.min(1, m.userData.rough + .2 * s / 2);
      if (m.userData.tag === "metal") m.metalness = Math.max(.1, .55 - .2 * s);
    });
    draw();
  }

  const tilesEl = $("#tiles");
  const views = MODELS.map(([id, build], k) => {
    const it = BYID[id];
    const b = document.createElement("button");
    b.type = "button"; b.className = "tile"; b.id = "tile-" + id;
    b.setAttribute("aria-label", `Ver ${it ? it.n : id} no catálogo`);
    b.innerHTML = `<div class="view"></div><div class="cap"><strong>${esc(it ? it.n : id)}</strong><span>${it ? fmt(it.kg) + " kg · " + RNAME[it.rar] : ""}</span></div>`;
    tilesEl.appendChild(b);
    const scene = new T.Scene();
    scene.add(new T.HemisphereLight(0xdfe6ee, 0x3a3428, .85));
    const sun = new T.DirectionalLight(0xffe2bf, 1.1); sun.position.set(2.5, 3.5, 2.5); scene.add(sun);
    const rim = new T.DirectionalLight(0x8fb2d6, .45); rim.position.set(-3, 1, -2.5); scene.add(rim);
    const obj = build();
    const bb = new T.Box3().setFromObject(obj), size = new T.Vector3(), ctr = new T.Vector3();
    bb.getSize(size); bb.getCenter(ctr);
    const sc = 1.55 / Math.max(size.x, size.y, size.z);
    const pivot = new T.Group(); obj.position.sub(ctr); pivot.add(obj); pivot.scale.setScalar(sc);
    pivot.rotation.set(.25, -.6 + k * .37, 0);
    scene.add(pivot);
    const cam = new T.PerspectiveCamera(30, 1, .1, 30); cam.position.set(0, .45, 3.6); cam.lookAt(0, 0, 0);
    const v = { id, el: b.querySelector(".view"), scene, cam, pivot, drag: false, spin: reduce ? 0 : .35 + (k % 3) * .06 };
    let lx = 0, moved = 0;
    v.el.addEventListener("pointerdown", e => { v.drag = true; lx = e.clientX; moved = 0; v.el.setPointerCapture(e.pointerId); });
    v.el.addEventListener("pointermove", e => { if (!v.drag) return; const dx = e.clientX - lx; lx = e.clientX; moved += Math.abs(dx); pivot.rotation.y += dx * .012; draw(); });
    v.el.addEventListener("pointerup", () => { v.drag = false; });
    b.addEventListener("click", e => { if (moved > 6) { moved = 0; e.preventDefault(); return; } showItem(id); });
    return v;
  });

  function size() {
    const w = box.clientWidth, h = box.clientHeight;
    if (canvas.width !== Math.floor(w * renderer.getPixelRatio()) || canvas.height !== Math.floor(h * renderer.getPixelRatio())) renderer.setSize(w, h, false);
  }
  function draw() {
    size();
    const br = box.getBoundingClientRect(), H = box.clientHeight;
    renderer.setScissor(0, 0, box.clientWidth, H); renderer.clear();
    for (const v of views) {
      const r = v.el.getBoundingClientRect();
      if (r.bottom < 0 || r.top > innerHeight) continue;
      const x = r.left - br.left, y = H - (r.bottom - br.top);
      renderer.setViewport(x, y, r.width, r.height); renderer.setScissor(x, y, r.width, r.height);
      renderer.render(v.scene, v.cam);
    }
  }
